#!/usr/bin/env bash
# Author: Miguel Simões
# SPDX-FileCopyrightText: 2026 Miguel Simões
# SPDX-License-Identifier: Apache-2.0
#
# RX/TX regression: reference RTL (a git revision, default upstream-baseline)
# against the working tree, on the upstream testbenches, over a matrix of
# packets and channel impairments generated by the Python bit-true model.
#
# For every configuration both designs must produce the SAME verdict and the
# SAME output files, byte for byte. A configuration that fails on both designs
# (for example at low SNR) is a model limitation, not a regression; it is
# reported as such, never as a pass.
#
# Usage (WSL/Linux, repository root):  scripts/validation/run_rx_regression.sh <label> [ref-rev]
# Env: OSS_CAD (default ~/eda/oss-cad-suite-20260907), PY (default ~/venvs/btle/bin/python)
#      DUT_DEFAULTS="<file>:<PARAM>=<value> ..." (default: none) rewrites a parameter
#      default in the dut copy only, so the upstream testbenches, which instantiate the
#      modules with their defaults, exercise that configuration. Example, branch
#      ble-tx-table: DUT_DEFAULTS="gauss_filter.v:GAUSS_TABLE=1".
# Output: results/validation/<label>/rx_regression/ (refuses to overwrite)

set -euo pipefail

label=${1:?usage: run_rx_regression.sh <label> [ref-rev]}
ref_rev=${2:-upstream-baseline}
OSS_CAD=${OSS_CAD:-$HOME/eda/oss-cad-suite-20260907}
PY=${PY:-$HOME/venvs/btle/bin/python}
export PATH=$OSS_CAD/bin:$PATH
export MPLBACKEND=Agg

repo=$(git rev-parse --show-toplevel)
out=$repo/results/validation/$label/rx_regression
[ -e "$out" ] && { echo "$out exists; choose a new label" >&2; exit 1; }
mkdir -p "$out"
work=$(mktemp -d /tmp/btle_rxreg.XXXXXX)

# Matrix: example (0 ADV ch37, 1 CONNECTION_UPDATE_REQ ch9, 2 LL_DATA ch10)
#         x SNR dB x clock error ppm x extra sample delay
examples=(0 1 2)
snrs=(20 12 8)
ppms=(0 20 50)
delays=(0 5)
tbs=(gfsk_demodulation_tb btle_rx_core_tb btle_rx_tb btle_tx_tb btle_controller_tb)

# Designs: ref = git revision, dut = working tree
mkdir -p "$work/ref" "$work/dut"
git -C "$repo" archive "$ref_rev" verilog | tar -x -C "$work/ref"
cp -r "$repo/verilog" "$work/dut/"
git -C "$repo" archive "$ref_rev" python | tar -x -C "$work"
DUT_DEFAULTS=${DUT_DEFAULTS:-}
for spec in $DUT_DEFAULTS; do
  f=${spec%%:*}; kv=${spec#*:}; p=${kv%%=*}; v=${kv#*=}
  sed -E -i "s/(parameter integer $p = )[0-9]+/\\1$v/" "$work/dut/verilog/$f"
  grep -qE "parameter integer $p = $v([^0-9]|\$)" "$work/dut/verilog/$f" \
    || { echo "DUT_DEFAULTS: $spec was not applied" >&2; exit 1; }
done

# Each design is compiled with the file list from ITS OWN testbench header.
# The upstream btle_controller_tb.v does not compile in Icarus (issue U9:
# signals used before their declaration); the reference is therefore run with
# the working-tree harness, whose only change is moving those declarations.
declare -A cmd_of
for d in ref dut; do for tb in "${tbs[@]}"; do
  cmd_of[$d.$tb]=$(grep -m1 -o "iverilog -o $tb .*" "$work/$d/verilog/$tb.v" | tr -d '\r')
done; done
cp "$work/dut/verilog/btle_controller_tb.v" "$work/ref/verilog/btle_controller_tb.v"

{
  echo "label=$label"
  echo "date_utc=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  echo "ref_rev=$ref_rev ($(git -C "$repo" rev-parse "$ref_rev^{commit}"))"
  echo "dut=working tree at $(git -C "$repo" rev-parse HEAD), dirty verilog files: $(git -C "$repo" status --porcelain -- verilog | wc -l)"
  echo "dut_defaults=${DUT_DEFAULTS:-<none: module defaults>}"
  echo "iverilog=$(iverilog -V 2>&1 | head -1)"
  echo "python=$($PY --version) numpy=$($PY -c 'import numpy; print(numpy.__version__)')"
  echo "matrix: examples=${examples[*]} snr=${snrs[*]} ppm=${ppms[*]} delay=${delays[*]}"
  echo "testbenches=${tbs[*]}"
} > "$out/provenance.txt"

for d in ref dut; do for tb in "${tbs[@]}"; do
  (cd "$work/$d/verilog" && eval "${cmd_of[$d.$tb]}") > "$work/$d/compile_$tb.log" 2>&1 \
    || { echo "compile failed: $d $tb" >&2; cat "$work/$d/compile_$tb.log" >&2; exit 1; }
done; done

summary=$out/summary.tsv
printf 'config\ttestbench\tref_verdict\tdut_verdict\toutputs\tresult\n' > "$summary"
n_same=0; n_diff=0; n_bothfail=0

for ex in "${examples[@]}"; do for snr in "${snrs[@]}"; do for ppm in "${ppms[@]}"; do for dl in "${delays[@]}"; do
  cfg="ex${ex}_snr${snr}_ppm${ppm}_d${dl}"
  gen=$work/gen_$cfg
  mkdir -p "$gen/verilog"
  cp -r "$work/python" "$gen/"
  (cd "$gen/python" && $PY test_vector_for_btle_verilog.py "$ex" "$snr" "$ppm" "$dl") > "$out/gen_$cfg.log" 2>&1
  (cd "$gen/verilog" && sha256sum *.txt) > "$out/vectors_$cfg.sha256"
  for tb in "${tbs[@]}"; do
    for d in ref dut; do
      run=$work/run_${d}_${cfg}_$tb
      cp -r "$work/$d/verilog" "$run"
      cp "$gen/verilog/"*.txt "$run/"
      (cd "$run" && timeout 1800 vvp -n "$tb") > "$run/sim.log" 2>&1 || true
      grep -iE 'test pass|test fail|difference found|error found' "$run/sim.log" | tr -d '\r' > "$run/verdict.txt" || true
    done
    r=$work/run_ref_${cfg}_$tb; u=$work/run_dut_${cfg}_$tb
    rv=$(tr '\n' ' ' < "$r/verdict.txt"); uv=$(tr '\n' ' ' < "$u/verdict.txt")
    # every output file the testbench wrote (anything not an input vector)
    outs_same=yes
    for f in $( (cd "$r" && ls *output*.txt; cd "$u" && ls *output*.txt) 2>/dev/null | grep -v '_ref\.txt$' | sort -u); do
      cmp -s "$r/$f" "$u/$f" || outs_same="no($f)"
    done
    if [ "$rv" == "$uv" ] && [ "$outs_same" == yes ]; then
      if echo "$rv" | grep -qiE 'fail|[1-9][0-9]* (difference|error) found'; then
        res=SAME_BOTH_FAIL; n_bothfail=$((n_bothfail+1))
      else
        res=SAME_PASS
      fi
      n_same=$((n_same+1))
    else
      res=DIFFERENT; n_diff=$((n_diff+1))
    fi
    printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$cfg" "$tb" "$rv" "$uv" "$outs_same" "$res" >> "$summary"
  done
  rm -rf "$gen" "$work"/run_*_"$cfg"_*
done; done; done; done

total=$((n_same+n_diff))
{
  echo "runs=$total identical=$n_same different=$n_diff (of the identical: both_fail=$n_bothfail)"
  [ $n_diff -eq 0 ] && echo "RESULT: PASS (every run identical between ref and dut)" || echo "RESULT: FAIL"
} | tee "$out/result.txt"
rm -rf "$work"
[ $n_diff -eq 0 ]
